namespace ghidra.app.plugin.core.compositeeditor;



using docking;
using generic.theme;
using ghidra.app.util.datatype;
using ghidra.program.model.data;

/**
 * ApplyAction is an action for applying editor changes.
 */
public class ApplyAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Apply Editor Changes";
	private static string GROUP_NAME = MAIN_ACTION_GROUP;
	private static Icon ICON = new GIcon("icon.plugin.composite.editor.apply");
	private static string[] POPUP_PATH = new string[] { "Apply Edits" };

	public ApplyAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, ICON)
    {

		setDescription("Apply editor changes");
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}

		provider.editorPanel.comitEntryChanges();

		try {
			model.apply();
		}
		catch (Exception e) when (e is EmptyCompositeException or InvalidDataTypeException) {
			model.setStatus(e.getMessage(), true);
		}
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (hasIncompleteFieldEntry()) {
			return false;
		}
		return model.hasChanges() && model.isValidName();
	}
}
